contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 newFee) public payable {
        // this contract is the owner (it deployed c), so onlyOwner passes
        bool reverted;
        if (newFee >= 30) {
            try c.setFee(newFee) { reverted = false; } catch { reverted = true; }
        } else {
            c.setFee(newFee);
            reverted = false;
        }
        uint256 stored = c.fee();
        if (newFee >= 30) {
            assert(reverted && stored < 30);
        } else {
            assert(!reverted && stored == newFee);
        }
    }
    receive() external payable {}
}

