contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] calldata whitelist,
        address[] calldata floorTokens,
        C.ERC20Asset[] calldata erc20Assets,
        C.ERC721Asset[] calldata erc721Assets
    ) public {
        require(expiration > block.timestamp);
        require(duration < 10_000 days);

        C.Order memory order = C.Order({
            maker: address(this),
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bool reverted;
        bytes32 orderHash = c.hashOrder(order);
        bool cancelledBefore = c.cancelledOrders(orderHash);
        try c.cancel(order) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            !reverted &&
            !cancelledBefore &&
            c.cancelledOrders(orderHash) &&
            !c.cancelledOrders(c.hashOppositeOrder(order))
        );
    }

    receive() external payable {}
}

