contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        bool isCall,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public {
        require(baseAsset != address(0));
        require(baseAsset != address(this));

        address[] memory emptyWhitelist = new address[](0);
        address[] memory emptyFloorTokens = new address[](0);
        C.ERC20Asset[] memory emptyErc20 = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory emptyErc721 = new C.ERC721Asset[](0);

        // Order made by a third party: cancel must revert for us.
        C.Order memory orderOther = C.Order({
            maker: baseAsset,
            isCall: isCall,
            isLong: true,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: emptyWhitelist,
            floorTokens: emptyFloorTokens,
            erc20Assets: emptyErc20,
            erc721Assets: emptyErc721
        });

        bool revertedOther;
        try c.cancel(orderOther) { revertedOther = false; } catch { revertedOther = true; }

        // Same order but with us as maker: cancel must succeed.
        C.Order memory orderSelf = C.Order({
            maker: address(this),
            isCall: isCall,
            isLong: true,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: emptyWhitelist,
            floorTokens: emptyFloorTokens,
            erc20Assets: emptyErc20,
            erc721Assets: emptyErc721
        });

        bytes32 selfHash = c.hashOrder(orderSelf);
        bool revertedSelf;
        try c.cancel(orderSelf) { revertedSelf = false; } catch { revertedSelf = true; }

        assert(
            revertedOther
            && !revertedSelf
            && c.cancelledOrders(selfHash)
        );
    }
}

